for _ in range(int(input())):
	n = int(input())
	a = list(map(int, input().split()))
	b = list(map(int, input().split()))
	a.sort()
	b.sort()
	m = min(b) - min(a)
	M = max(b) - max(a)
	if M <= 0:
		print(m)
	elif n == 2:
		print(min(m, M))
	elif b[0] - a[1] == M:
		print(M)
	else:
		print(m)
